--region 凡妮莎法奥斯生态AI
---@class XCharVanessaEcology : XEcologyConstructAIBase
---@field _stateMachine XStateMachineController 状态机
local XCharVanessaEcology = XDlcScriptManager.RegCharScript(10610401, "XCharVanessaEcology", Base)

--- 注册状态机状态
function XCharVanessaEcology:RegisterMachineState()
    self._stateMachine:AddState(StateEnum.InClass, XVanessaInClassState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.TrainingRoom, XVanessaTrainingRoomState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.FacingView, XVanessaFacingViewState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.Podium, XVanessaPodiumState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.FindPath, XVanessaFindPathState.New(self._proxy))
end

--- 注册状态转移方程
function XCharVanessaEcology:RegisterMachineStateTransition()
    -- 设置寻路状态枚举值
    self.FindPathStateEnum = StateEnum.FindPath
    -- 其他状态到寻路状态
    self:RegisterInFindPathStateTransition(StateEnum.InClass, function()
        if self._stateMachine:CheckDataBoard(DataBoardKey.InClass2, 1) and 
                self._stateMachine:CheckDataBoard(DataBoardKey.TrainingRoom2, 1) and
                self._stateMachine:CheckDataBoard(DataBoardKey.FacingView2, 1) then
            return StateEnum.Podium
        else 
            return StateEnum.TrainingRoom
        end
    end, 30, 1)
    self:RegisterInFindPathStateTransition(StateEnum.TrainingRoom, function()
        if self._stateMachine:CheckDataBoard(DataBoardKey.InClass2, 1) and
                self._stateMachine:CheckDataBoard(DataBoardKey.TrainingRoom2, 1) and
                self._stateMachine:CheckDataBoard(DataBoardKey.FacingView2, 1) then
            return StateEnum.Podium
        else 
            return StateEnum.FacingView
        end
    end , 30, 1)
    self:RegisterInFindPathStateTransition(StateEnum.Podium, function()
        if self._stateMachine:CheckDataBoard(DataBoardKey.Podium, 1) then 
            return StateEnum.InClass
        elseif self._stateMachine:CheckDataBoard(DataBoardKey.Podium, 2) then 
            return StateEnum.TrainingRoom
        elseif self._stateMachine:CheckDataBoard(DataBoardKey.Podium, 3) then 
            return StateEnum.FacingView
        end
    end, 30, 1)
    self:RegisterInFindPathStateTransition(StateEnum.FacingView, function()
        if self._stateMachine:CheckDataBoard(DataBoardKey.InClass2, 1) and
                self._stateMachine:CheckDataBoard(DataBoardKey.TrainingRoom2, 1) and
                self._stateMachine:CheckDataBoard(DataBoardKey.FacingView2, 1) then
            return StateEnum.Podium
        else 
            return StateEnum.InClass
        end
    end , 30, 1)
    
    -- 寻路状态到其他状态
    self:RegisterOutFindPathStateTransition(StateEnum.InClass)
    self:RegisterOutFindPathStateTransition(StateEnum.TrainingRoom)
    self:RegisterOutFindPathStateTransition(StateEnum.FacingView)
    self:RegisterOutFindPathStateTransition(StateEnum.Podium)
end

return XCharVanessaEcology
--endregion
